SELECT f.page_id,f.slot,HEX(f.hash) current_hash,r.title,f.written,f.referenced,f.wait_days,v.born_rev written_rev,ev.user written_by,fr.born_rev reference_rev,er.user reference_by,HEX(fr.hash) reference_hash,t.wikitext first_ref_wikitext,t.text after_text,t0.text original_text,tc.wikitext current_wikitext,tc.text current_text FROM facts f JOIN first_versions v USING(page_id,slot) JOIN first_refs fr USING(page_id,slot) JOIN wtt.passage_text t ON t.hash=fr.hash JOIN wtt.passage_text t0 ON t0.hash=v.hash JOIN wtt.passage_text tc ON tc.hash=f.hash JOIN wtt.revision r ON r.page_id=f.page_id LEFT JOIN wtt.edit ev ON ev.rev_id=v.born_rev LEFT JOIN wtt.edit er ON er.rev_id=fr.born_rev WHERE f.has_ref;
